import{z as E,x as A,o as i,c as B,q as s,j as r,D as e,d as l,s as t,S as o}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"噪声方差估计","description":"","frontmatter":{"title":"噪声方差估计","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/noise-variance-estimate.md","filePath":"quant/noise-variance-estimate.md","lastUpdated":1791413859000}'),p={name:"quant/noise-variance-estimate.md"};function m(d,a,_,h,c,u){const n=A("Mermaid");return i(),B("div",null,[a[2]||(a[2]=s('<h1 id="噪声方差估计" tabindex="-1">噪声方差估计 <a class="header-anchor" href="#噪声方差估计" aria-label="Permalink to &quot;噪声方差估计&quot;">​</a></h1><div class="epigraph"><p>签名图在高频端的上翘斜率，量的是微观结构噪声的二次贡献；把它估出来，既是市场质量的描述，也是 TSRV、核与预平均的带宽输入。</p><footer>—— Bandi and Russell, Separating Microstructure Noise from Volatility, Journal of Financial Economics, 2006；两尺度识别见 Zhang, Mykland and Aït-Sahalia</footer></div><p><a href="/quant/refresh-time">刷新时间</a> 改变了有效采样数 \\(n^*\\)。<a href="/quant/microstructure-noise">微观结构噪声</a> 给出 \\(\\mathbb{E}[\\mathrm{RV}]\\approx IV+2n\\sigma_\\varepsilon^2\\)。本课把 \\(\\sigma_\\varepsilon^2\\) 当成<strong>要估计的参数</strong>：Bandi 与 Russell 讨论用密采样矩分离噪声与波动；TSRV 的密网格项是同一矩。缺口是：\\(\\sigma_\\varepsilon^2\\) 随日、随股票、随是否用中点而变，固定带宽等于假装噪声水平恒定。下一课把大的剩余（跳）从噪声里分开，并接到新闻时刻。对象先是噪声二阶，不是跳。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>i.i.d. 加性噪声下，\\(\\mathrm{RV}_n/(2n)\\to_p\\sigma_\\varepsilon^2\\)（当 \\(n\\to\\infty\\) 且该项主导 \\(IV/n\\)）。有限 \\(n\\) 时 \\(IV/(2n)\\) 污染估计，需减一个稀疏 RV 或用 Bandi–Russell 的最优采样思想同时顾及两者。相关噪声下「\\(\\sigma_\\varepsilon^2\\)」变成短滞后谱，单标量不够，应报噪声的自相关长度或核估计的噪声部分。</p><p><span class="marginnote">拿数字感受噪声为何容易盖过波动：日波动 \\(IV=(1\\%)^2=10^{-4}\\)，噪声 \\(\\sigma_\\varepsilon=0.05\\%\\)，采样 \\(n=2000\\) 次，则噪声项 \\(2n\\sigma_\\varepsilon^2=2\\times2000\\times(5\\times10^{-4})^2=10^{-3}\\)，已是 \\(IV\\) 的十倍。这就是直接拿最细数据算 RV 会严重高估波动的算术原因。</span></p><p>问题：用成交价还是中点？成交价含 Roll 弹跳，\\(\\sigma_\\varepsilon\\) 更大，对应执行；中点更接近报价噪声。Hasbrouck 定价误差方差是另一度量（VAR 分解），与 RV 矩的 \\(\\sigma_\\varepsilon^2\\) 相关但不等。不要混名为「噪声」。</p><p>文献里至少有三个都叫「噪声」的量，对象各不相同：</p>',8)),(i(),r(o,null,{default:e(()=>[t(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%90%8C%E4%B8%80%E5%BE%AE%E8%A7%82%E7%BB%93%E6%9E%84%E7%8E%B0%E8%B1%A1%22%5D%20--%3E%20M1%5B%22RV%20%E7%9F%A9%E7%9A%84%20%CF%83_%CE%B5%C2%B2%22%5D%0A%20%20M1%20--%3E%20M1A%5B%22%E5%AF%86%E9%87%87%E6%A0%B7%20RV%20%E4%B8%8A%E7%BF%98%E7%9A%84%E4%BA%8C%E6%AC%A1%E8%B4%A1%E7%8C%AE%22%5D%0A%20%20P%20--%3E%20M2%5B%22Roll%20%E7%9A%84%20s%2F2%22%5D%0A%20%20M2%20--%3E%20M2A%5B%22%E6%9C%89%E6%95%88%E4%BB%B7%E5%B7%AE%E4%B8%80%E5%8D%8A%2C%20%E4%B9%B0%E5%8D%96%E5%BC%B9%E8%B7%B3%E5%B9%85%E5%BA%A6%22%5D%0A%20%20P%20--%3E%20M3%5B%22Hasbrouck%20%E5%AE%9A%E4%BB%B7%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20M3%20--%3E%20M3A%5B%22VAR%20%E5%88%86%E8%A7%A3%E5%87%BA%E7%9A%84%E9%9D%9E%E4%BF%A1%E6%81%AF%E9%83%A8%E5%88%86%22%5D%0A%20%20M1A%20--%3E%20C%5B%22%E7%9B%B8%E5%85%B3%E4%BD%86%E4%B8%8D%E7%9B%B8%E7%AD%89%2C%20%E4%B8%8D%E5%8F%AF%E6%B7%B7%E7%94%A8%E5%90%8C%E5%90%8D%22%5D%0A%20%20M2A%20--%3E%20C%0A%20%20M3A%20--%3E%20C%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s('<h3 id="签名图作为估计器" tabindex="-1">签名图作为估计器 <a class="header-anchor" href="#签名图作为估计器" aria-label="Permalink to &quot;签名图作为估计器&quot;">​</a></h3><p>横轴 \\(\\Delta\\) 或 \\(n\\)，纵轴 RV。高频段线性上翘的斜率识别 \\(2\\sigma_\\varepsilon^2\\)。中频平台识别 \\(IV\\)。估计应分两段拟合，而不是用全部频率做一次回归。开盘季节会让「平台」倾斜，先除季节或分段会话。</p><p><span class="marginnote">\\(\\hat\\sigma_\\varepsilon\\) 可与有效价差对照：Roll 说 \\(\\sigma_\\varepsilon\\) 与 \\(s/2\\) 同阶。数量级对不上时，多半是相关噪声、错数据或网格不是成交时钟。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>简单矩。</strong> \\(\\widehat{\\sigma}_\\varepsilon^2=\\max\\bigl(0,(\\mathrm{RV}^{\\mathrm{all}}-\\mathrm{RV}^{\\mathrm{sparse}})/(2(n-\\bar n))\\bigr)\\)。与 TSRV 同源。负值截断。</p><p><strong>Bandi–Russell。</strong> 选择使 MSE 最小的采样频率，隐含噪声与 \\(IV\\) 的权衡；可产出噪声估计作为副产品。最优频率随日变，这正是自适应带宽的理由。</p><p><strong>预平均/核的副产品。</strong> 许多一致 \\(IV\\) 估计量同时一致（或可）估噪声矩。应与主估计同一套清洗和刷新。刷新后 \\(n\\) 用 \\(n^*\\)。</p><p><strong>诊断。</strong> 日序列 \\(\\{\\hat\\sigma_{\\varepsilon,t}\\}\\) 应与价差、深度同向；危机日噪声升。若与 \\(IV\\) 几乎完全共线，可能没分离开（带宽太短，IV 漏进噪声项）。</p><h3 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h3><ol><li>选 \\(k\\)、\\(K\\)、核 \\(H\\)；2. 市场质量横截面（与价差、Hasbrouck 并列）；3. 判断五分钟是否够疏。不要把 \\(\\hat\\sigma_\\varepsilon\\) 当 alpha 信号——它慢变、易被制度改变。</li></ol><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>密采样下 \\(\\Delta Y\\approx\\Delta\\varepsilon\\)，平方和数的是噪声二次变差。稀疏时 \\(\\Delta X\\) 主导。差的期望隔离噪声。相关噪声：\\(\\Delta\\varepsilon\\) 的平方和还含 \\(2\\mathrm{Cov}(\\varepsilon_i,\\varepsilon_{i-1})\\) 一类，Roll 负相关会改变系数 2。机制上必须先看收益一阶 ACF：强负是弹跳，应用 Roll 结构；弱相关或正，噪声模型更脏，标量 \\(\\sigma_\\varepsilon^2\\) 只是有效值。</p><p><span class="marginnote">直觉类比：把价格想成「真实价值走楼梯 + 抖动的镜头」——\\(IV\\) 是楼梯的真实起伏，\\(\\sigma_\\varepsilon^2\\) 是镜头抖动的方差。采样越密，抖动被平方累加的次数越多，RV 的高频端于是上翘：量到的越来越是镜头，而不是楼梯。</span></p><p>圆整：价格落在 tick 网格，\\(\\varepsilon\\) 有界、非高斯，密采样 RV 的上翘仍在，但渐近公式的常数变。小价格股应报 tick 占价格的比例。</p><p><span class="marginnote">把所有零收益（日历插值）算进 \\(n\\)，会把 \\(\\sigma_\\varepsilon^2\\) 估崩。\\(n\\) 必须是真实更新次数或刷新格数。</span></p><h3 id="到跳跃与新闻的交接" tabindex="-1">到跳跃与新闻的交接 <a class="header-anchor" href="#到跳跃与新闻的交接" aria-label="Permalink to &quot;到跳跃与新闻的交接&quot;">​</a></h3><p>噪声是高频、反向、暂时；跳是持久的水平移动。签名图上噪声随频率上翘，跳抬高所有频率的平台。下一课用这个几何把新闻跳从噪声里分开，并接到公告时钟。若把跳日的平台抬高当成 \\(\\sigma_\\varepsilon\\) 升，会错误加长核带宽、把跳平滑进 \\(IV\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>极薄股票 \\(n\\) 小，分离失败，应放弃密采样噪声估计，只用五分钟当 \\(IV\\)、用报价价差当质量。盘前盘后噪声结构不同，不要并入连续竞价样本。</p><p>工程：每日估 \\(\\sigma_\\varepsilon^2\\) 用于自适应带宽；横截面用中位数日。与有效价差对照。不要用未清洗 tick。不要跨日拼接估一个 \\(\\sigma_\\varepsilon\\)。下一课：跳与新闻。</p>',20)),(i(),r(o,null,{default:e(()=>[t(n,{id:"mermaid-87",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%E7%AD%BE%E5%90%8D%E5%9B%BE%20RV(%CE%94)%22%5D%20--%3E%20HI%5B%22%E9%AB%98%E9%A2%91%E4%B8%8A%E7%BF%98%20%E2%86%92%20%E5%99%AA%E5%A3%B0%22%5D%0A%20%20SIG%20--%3E%20MID%5B%22%E4%B8%AD%E9%A2%91%E5%B9%B3%E5%8F%B0%20%E2%86%92%20IV%22%5D%0A%20%20HI%20--%3E%20SE%5B%22%CF%83%CC%82_%CE%B5%C2%B2%22%5D%0A%20%20SE%20--%3E%20BW%5B%22%E6%A0%B8%20%2F%20%E9%A2%84%E5%B9%B3%E5%9D%87%20%2F%20TSRV%20%E5%B8%A6%E5%AE%BD%22%5D%0A%20%20SE%20--%3E%20MQ%5B%22%E5%B8%82%E5%9C%BA%E8%B4%A8%E9%87%8F%E6%8F%8F%E8%BF%B0%22%5D%0A%20%20JUMP%5B%22%E8%B7%B3%22%5D%20--%3E%20PLAT%5B%22%E6%8A%AC%E9%AB%98%E6%89%80%E6%9C%89%E9%A2%91%E7%8E%87%22%5D%0A%20%20PLAT%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E4%B8%8D%E8%A6%81%E6%8A%8A%E8%B7%B3%E5%BD%93%E6%88%90%E5%99%AA%E5%A3%B0%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=s('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>密网格 RV 主导项是 \\(2n\\sigma_\\varepsilon^2\\)，可识别噪声方差；须用对的 \\(n\\)（刷新、真实更新）。</li><li>相关噪声、圆整、季节会改变系数；标量 \\(\\hat\\sigma_\\varepsilon^2\\) 是有效值，应与价差对照。</li><li>主用途是自适应带宽与市场质量，不是交易信号。</li><li>跳抬平台、噪声抬高频端，分离失败会把带宽选错。</li><li>出处：Bandi and Russell, <em>Journal of Financial Economics</em>, 2006；Zhang, Mykland and Aït-Sahalia, <em>JASA</em>, 2005；Roll 价差与 Hasbrouck 定价误差为对照度量。</li></ul>',2))])}const V=E(p,[["render",m]]);export{D as __pageData,V as default};
